/** Sets the setting: a dated one records its value from the from-date given (the sheet's today when none was), keeping the others. */
public class ApplySetting {
    public void apply(@Val SheetResponse sheet, @Val SettingInput input, SettingRepository repository,
            SheetRepository sheets, Out<Setting> setting) {
        if (!Setting.isDated(input.key())) {
            setting.set(repository.set(sheet.id(), input.key(), input.value()));
            return;
        }
        repository.setFrom(sheet.id(), input.key(), input.from() != null ? input.from() : sheets.today(sheet.id()),
                input.value());
        setting.set(new Setting(sheet.id(), input.key(), input.value(), input.from()));
    }
}
package net.officefloor.hq.app.access;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/**
 * The settings on each sheet, by key; a key without a row is blank. A dated setting (see {@link Setting#isDated}) keeps
 * every value saved, each from its from-date; the one in force on a date is the latest from on or before it (see
 * {@link DatedSettings}).
 */
@Repository
public class SettingRepository {

    private static final RowMapper<Setting> ROW = (rs, n) -> new Setting(rs.getString("sheet_id"),
            rs.getString("setting_key"), rs.getString("setting_value"), null);

    private static final RowMapper<DatedValue> DATED = (rs, n) -> new DatedValue(rs.getString("setting_key"),
            rs.getObject("from_date", LocalDate.class), rs.getString("setting_value"));

    private final JdbcTemplate jdbc;

    public SettingRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's undated settings, by key (the policy date, period numbering from, the grace days and the permissions); a key without a row is not listed. */
    public List<Setting> listUndated(String sheetId) {
        return jdbc.query("SELECT sheet_id, setting_key, setting_value FROM sheet_setting WHERE sheet_id = ?"
                + " ORDER BY setting_key", ROW, sheetId);
    }

    /** The sheet's dated settings: every value recorded, by key and from-date. */
    public DatedSettings dated(String sheetId) {
        return new DatedSettings(jdbc.query("SELECT setting_key, from_date, setting_value FROM sheet_setting_from"
                + " WHERE sheet_id = ? ORDER BY setting_key, from_date", DATED, sheetId));
    }

    /** The undated setting's value; null when blank. */
    public String find(String sheetId, String key) {
        return jdbc.query("SELECT sheet_id, setting_key, setting_value FROM sheet_setting WHERE sheet_id = ?"
                + " AND setting_key = ?", ROW, sheetId, key).stream().findFirst().map(Setting::value).orElse(null);
    }

    /** Whether the role may take the action (open, settle, void, reassign, close, reopen): its permission's roles, else the standing rule. */
    public boolean allows(String sheetId, String action, String role) {
        String value = find(sheetId, Setting.PERMISSION + action);
        List<String> roles = value == null ? Setting.PERMISSION_STANDING.get(action) : List.of(value.split(","));
        return roles.contains(role);
    }

    /** A person's due-total held to the cap: the cap when it is above it; n/a (null) and no cap leave it as it is. */
    public static BigDecimal capped(BigDecimal dueTotal, BigDecimal cap) {
        return dueTotal == null || cap == null || dueTotal.compareTo(cap) <= 0 ? dueTotal : cap;
    }

    /** The sheet's policy date: the one set, else its today. */
    public LocalDate policyDate(String sheetId, LocalDate today) {
        String value = find(sheetId, Setting.POLICY_DATE);
        return value == null ? today : LocalDate.parse(value);
    }

    /** The sheet's period numbering from-date; null while off. */
    public LocalDate periodNumberingFrom(String sheetId) {
        String value = find(sheetId, Setting.PERIOD_NUMBERING_FROM);
        return value == null ? null : LocalDate.parse(value);
    }

    /** The sheet's grace days; null while off. */
    public Integer graceDays(String sheetId) {
        String value = find(sheetId, Setting.GRACE_DAYS);
        return value == null ? null : Integer.valueOf(value);
    }

    /** The sheet's late charge as of its today, each 30-day boundary's late percent the one in force on its date, with its policy date for rounding. */
    public LateCharge lateCharge(String sheetId, LocalDate today) {
        return new LateCharge(today, dated(sheetId), policyDate(sheetId, today));
    }

    /** Set an undated setting's value (null: blank), replacing the one there before. */
    public Setting set(String sheetId, String key, String value) {
        jdbc.update("MERGE INTO sheet_setting (sheet_id, setting_key, setting_value) KEY (sheet_id, setting_key)"
                + " VALUES (?, ?, ?)", sheetId, key, value);
        return new Setting(sheetId, key, value, null);
    }

    /** Record a dated setting's value (null: blank) from the date, keeping the others; one already from that date is replaced. */
    public void setFrom(String sheetId, String key, LocalDate from, String value) {
        jdbc.update("MERGE INTO sheet_setting_from (sheet_id, setting_key, from_date, setting_value)"
                + " KEY (sheet_id, setting_key, from_date) VALUES (?, ?, ?, ?)", sheetId, key, from, value);
    }

    /** Every setting as of the date: each dated key's value in force then (its starting value, or blank), and the undated ones set. */
    public List<SettingResponse> listOn(String sheetId, LocalDate today) {
        DatedSettings dated = dated(sheetId);
        List<SettingResponse> found = new ArrayList<>();
        java.util.Set<String> keys = new java.util.TreeSet<>(List.of(Setting.FLOOR, Setting.TERMS, Setting.LATE_PCT));
        dated.values().forEach(v -> keys.add(v.key()));
        for (String key : keys) {
            found.add(new SettingResponse(key, dated.on(key, today), dated.values().stream()
                    .filter(v -> v.key().equals(key))
                    .map(v -> new SettingResponse.From(v.from().toString(), v.value())).toList()));
        }
        listUndated(sheetId).forEach(s -> found.add(new SettingResponse(s.key(), s.value(), List.of())));
        return found;
    }
}
package net.officefloor.hq.app.access;

/** A setting on a sheet: its key and value (null: blank), and the from-date it was saved from when one was given (null otherwise). */
public record Setting(String sheetId, String key, String value, java.time.LocalDate from) {

    /** Whether the key's setting is dated: one that carries a figure (every key but the policy date, period numbering from, the grace days and the permissions). */
    public static boolean isDated(String key) {
        return !POLICY_DATE.equals(key) && !PERIOD_NUMBERING_FROM.equals(key) && !GRACE_DAYS.equals(key) && !isPermission(key);
    }

    /** Whether the key is one of the permission matrix's (perm-<action>). */
    public static boolean isPermission(String key) {
        return key.startsWith(PERMISSION) && PERMISSION_STANDING.containsKey(key.substring(PERMISSION.length()));
    }

    /** The value a dated key has before every from-date: the floor's, the terms' and the late percent's starting value; null (blank) for the rest. */
    public static String starting(String key) {
        return switch (key) {
            case FLOOR -> FLOOR_DEFAULT;
            case TERMS -> TERMS_DEFAULT;
            case LATE_PCT -> LATE_PCT_DEFAULT;
            default -> null;
        };
    }

    /** The most a clerk may settle a claim's due for; blank means no limit. */
    public static final String CLERK_LIMIT = "clerk-limit";

    /** The due above which a claim needs a proof before it is settled or approved; blank means none. */
    public static final String PROOF_THRESHOLD = "proof-threshold";

    /** The most a person's due-total may be; an amount with two decimals, blank for none. */
    public static final String CAP = "cap";

    /** The least a claim's live due may be; an amount with two decimals. */
    public static final String FLOOR = "floor";

    /** The floor a sheet starts with, until it is set. */
    public static final String FLOOR_DEFAULT = "1.00";

    /** The number of days after its date a claim is due by; a whole number. */
    public static final String TERMS = "terms";

    /** The terms a sheet starts with, until they are set. */
    public static final String TERMS_DEFAULT = "14";

    /** A grade's own terms (the key is this plus the grade, terms-A); blank means the sheet's terms. */
    public static final String TERMS_OF_GRADE = "terms-";

    /** The grades that may have their own terms. */
    public static final java.util.Set<String> GRADES = java.util.Set.of("A", "B", "C");

    /** The percent of its figure an overdue claim's due gains for every full 30 days it is overdue, the one in force on each 30-day boundary date; two decimals. */
    public static final String LATE_PCT = "late-pct";

    /** The late percent a sheet starts with, until it is set. */
    public static final String LATE_PCT_DEFAULT = "0.00";

    /** The date before which a claim's live figures round half up, and from which half to even; blank means the sheet's today. */
    public static final String POLICY_DATE = "policy-date";

    /** The date from which (on the sheet's today) an opened claim is numbered within its period; blank means off. */
    public static final String PERIOD_NUMBERING_FROM = "period-numbering-from";

    /** The days after its to-date an open period is closed by itself when the sheet's today moves past them; a whole number, blank for off. */
    public static final String GRACE_DAYS = "grace-days";

    /** The roles that may take an action (the key is this plus the action, perm-open): a comma separated list of roles, blank for the standing rule. */
    public static final String PERMISSION = "perm-";

    /** Each action's standing rule, the roles that may take it while its permission is blank. */
    public static final java.util.Map<String, java.util.List<String>> PERMISSION_STANDING = java.util.Map.of(
            "open", java.util.List.of(Role.CLERK, Role.STEWARD),
            "settle", java.util.List.of(Role.CLERK, Role.STEWARD),
            "void", java.util.List.of(Role.CLERK, Role.STEWARD),
            "close", java.util.List.of(Role.CLERK, Role.STEWARD),
            "reassign", java.util.List.of(Role.STEWARD),
            "reopen", java.util.List.of(Role.STEWARD));
}
